SELECT g.*, c.name AS couponName
FROM market_coupon_grant g
LEFT JOIN market_coupon c ON g.coupon_id = c.id
WHERE g.member_id = #{memberId}

  AND g.status = #{status}

ORDER BY g.created_at DESC

SELECT g.*, c.name AS couponName
FROM market_coupon_grant g
LEFT JOIN market_coupon c ON g.coupon_id = c.id
WHERE g.member_id = #{memberId} AND g.tenant_id = #{tenantId}

  AND g.status = #{status}

ORDER BY g.created_at DESC

mapper.insert:
INSERT INTO market_coupon_grant
    (coupon_id, member_id, tenant_id, code, status, source, expire_time)
SELECT
    #{couponId},
    #{memberId},
    #{tenantId},
    #{code},
    1,
    #{source},
    #{expireTime}
FROM DUAL
WHERE NOT EXISTS (
    SELECT 1 FROM market_coupon_grant
    WHERE coupon_id = #{couponId}
      AND member_id = #{memberId}
      AND tenant_id = #{tenantId}
      AND status != 3
)
  AND (
    SELECT COUNT(*)
    FROM market_coupon_grant
    WHERE coupon_id = #{couponId}
      AND tenant_id = #{tenantId}
      AND status != 3
  ) < (
    SELECT total_count
    FROM market_coupon
    WHERE id = #{couponId}
  )

mapper.update:
UPDATE market_coupon c
JOIN (
    SELECT id FROM market_coupon
    WHERE id = #{couponId}
      AND status = 1
      AND (start_time IS NULL OR start_time <= NOW())
      AND (end_time IS NULL OR end_time >= NOW())
      AND total_count > (
          SELECT COUNT(*) FROM market_coupon_grant
          WHERE coupon_id = #{couponId} AND deleted = 0
      )
      AND (
          per_limit IS NULL OR per_limit = 0
          OR (
              SELECT COUNT(*) FROM market_coupon_grant
              WHERE coupon_id = #{couponId}
                AND member_id = #{memberId}
                AND deleted = 0
          ) < per_limit
      )
    LIMIT 1
) sub ON c.id = sub.id
SET c.issued_count = c.issued_count + 1
WHERE c.id = #{couponId}
